<script setup>
import { ref,onMounted,onUnmounted } from 'vue'; import { useRoute } from 'vue-router'; import { api } from '../services/api'
const route=useRoute(),album=ref(null),photos=ref([]),page=ref(1),last=ref(1),selected=ref(-1),error=ref('')
async function load(){try{const [a,p]=await Promise.all([api.get('/albums/'+route.params.slug),api.get('/albums/'+route.params.slug+'/photos',{params:{page:page.value}})]);album.value=a.data;photos.value=p.data.data;last.value=p.data.last_page}catch{error.value='Album tidak ditemukan atau belum tersedia.'}}
function keys(e){if(selected.value<0)return;if(e.key==='Escape')selected.value=-1;if(e.key==='ArrowRight')selected.value=(selected.value+1)%photos.value.length;if(e.key==='ArrowLeft')selected.value=(selected.value-1+photos.value.length)%photos.value.length}
onMounted(()=>{load();window.addEventListener('keydown',keys)});onUnmounted(()=>window.removeEventListener('keydown',keys));function change(n){page.value=n;selected.value=-1;load()}
</script>
<template><main class="wrap listing"><router-link to="/albums" class="text-link">← Semua album</router-link><p v-if="error" class="notice">{{error}}</p><template v-if="album"><div class="eyebrow"><i></i> {{album.category?.name}}</div><h1>{{album.title}}<span>.</span></h1><p>{{album.description}}</p><div class="album-details"><span v-if="album.event_date">{{album.event_date.slice(0,10)}} &nbsp; · &nbsp; </span><span v-if="album.location">{{album.location}} &nbsp; · &nbsp; </span>{{album.photos_count}} foto</div><div class="photo-grid"><button v-for="(p,i) in photos" :key="p.id" @click="selected=i"><img :src="p.thumbnail_url" :alt="p.original_filename" loading="lazy"></button></div><p v-if="!photos.length" class="notice">Belum ada foto dalam album ini.</p><div class="pagination"><button :disabled="page<=1" @click="change(page-1)">← Sebelumnya</button><span>{{page}} / {{last}}</span><button :disabled="page>=last" @click="change(page+1)">Berikutnya →</button></div></template><div v-if="selected>=0" class="lightbox" @click.self="selected=-1"><button class="close" @click="selected=-1">×</button><button @click="selected=(selected-1+photos.length)%photos.length">←</button><figure><img :src="photos[selected].thumbnail_url" :alt="photos[selected].original_filename"><figcaption>{{photos[selected].original_filename}} · {{photos[selected].width}} × {{photos[selected].height}} <a :href="api.defaults.baseURL+'/photos/'+photos[selected].id+'/download'">↓ Unduh foto asli</a></figcaption></figure><button @click="selected=(selected+1)%photos.length">→</button></div></main></template>
